import fcntl
import os
import re
import subprocess
import time
import zipfile
from contextlib import contextmanager
from urllib.parse import quote

from openlibrary.coverstore import config, db

SIZES = ('', 's', 'm', 'l')


class Cover:
    def __init__(self, attributes):
        self.__dict__.update(attributes)

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        cover_id = int(cover_id)
        if not 0 <= cover_id < 10**10:
            raise ValueError('cover ID must fit in ten digits')
        padded = f'{cover_id:010d}'
        return padded[:4], padded[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        if size not in SIZES or protocol not in ('http', 'https'):
            raise ValueError('invalid size or protocol')
        if not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('invalid extension')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        filename = f'{int(cover_id):010d}{\"-\" + size.upper() if size else \"\"}.{ext}'
        return f'{protocol}://archive.org/download/{item}/{item}_{batch_id}.zip/{quote(filename)}'

    def valid_files(self):
        return all(
            getattr(self, field, None)
            and os.path.isfile(os.path.join(config.data_root, 'localdisk', getattr(self, field)))
            for field in ('filename', 'filename_s', 'filename_m', 'filename_l')
        )


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (int(start_id) // 10000 + 1) * 10000 - 1

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext='jpg'):
        item_id, batch_id = Batch(item_id, batch_id)._norm_ids()
        start_id = int(item_id) * 1000000 + int(batch_id) * 10000
        end_id = CoverDB._get_batch_end_id(start_id)
        database = db.getdb()
        transaction = database.transaction()
        try:
            rows = list(database.select('cover', where='id >= "'$start_id AND id <= $end_id AND archived = $yes AND failed = $no'"', vars={'start_id': start_id, 'end_id': end_id, 'yes': True, 'no': False}))
            for row in rows:
                urls = {('filename_' + size if size else 'filename'): Cover.get_cover_url(row.id, size, ext) for size in SIZES}
                database.update('cover', where='id="'$id AND archived=$yes AND failed=$no'"', vars={'id': row.id, 'yes': True, 'no': False}, uploaded=True, **urls)
            transaction.commit()
        except Exception:
            transaction.rollback()
            raise
        return len(rows)


class ZipManager:
    def __init__(self):
        self.zipfiles = {}

    def get_zipfile(self, name):
        match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.[A-Za-z0-9]+', name)
        if not match:
            raise ValueError(f'invalid cover filename: {name}')
        item_id, batch_id = Cover.id_to_item_and_batch_id(match[1])
        size = (match[2] or '').lower()
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            archive = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = (archive, set(archive.namelist()))
        return self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        archive, names = self.get_zipfile(name)
        if name not in names:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, archive.open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            names.add(name)
        return name

    def close(self):
        for archive, _ in self.zipfiles.values():
            archive.close()
        self.zipfiles.clear()


def open_zipfile(name):
    manager = ZipManager()
    archive, _ = manager.get_zipfile(name)
    return archive


def get_zipfile(name):
    return open_zipfile(name)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith('.jpg') for name in archive.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return subprocess.run(['ia', 'upload', itemname, *filepaths], capture_output=True, text=True, check=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = subprocess.run(['ia', 'list', item], capture_output=True, text=True, check=True)
        found = zip_filename in result.stdout.splitlines()
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


def is_uploaded(item, zip_filename):
    return Uploader.is_uploaded(item, zip_filename)


@contextmanager
def _batch_lock(item_id, batch_id):
    \"\"\"Serialize work on a batch across processes sharing the staging directory.\"\"\"
    lockpath = Batch.get_abspath(item_id, batch_id) + '.lock'
    os.makedirs(os.path.dirname(lockpath), exist_ok=True)
    with open(lockpath, 'a+b') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id = item_id
        self.batch_id = batch_id
        self.size = size
        self._norm_ids()
        if size is not None and size not in SIZES:
            raise ValueError('invalid size')

    def _norm_ids(self):
        item_id, batch_id = int(self.item_id), int(self.batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('invalid item or batch ID')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls(item_id, batch_id)._norm_ids()
        if size not in SIZES or not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('invalid size or extension')
        item = f'{size + \"_\" if size else \"\"}covers_{item_id}'
        return os.path.join('items', item, f'{item}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        uploader = uploader or Uploader()
        item_id, batch_id = self._norm_ids()
        sizes = SIZES if self.size is None else (self.size,)
        with _batch_lock(item_id, batch_id):
            ready = True
            for size in sizes:
                path = self.get_abspath(item_id, batch_id, size)
                if not os.path.isfile(path):
                    ready = False
                    continue
                item = f'{size + \"_\" if size else \"\"}covers_{item_id}'
                if upload and not test and not uploader.is_uploaded(item, os.path.basename(path)):
                    uploader.upload(item, [path])
                if not uploader.is_uploaded(item, os.path.basename(path)):
                    ready = False
            # A cover has four variants; never publish only part of a batch.
            if finalize and ready and len(sizes) == len(SIZES) and not test:
                self.finalize()
            return ready

    def finalize(self, start_id=None, test=False):
        if test:
            return 0
        item_id, batch_id = self._norm_ids()
        return CoverDB.update_completed_batch(item_id, batch_id)


def archive(test=True):
    \"\"\"Stage one 10k ID range; keep local files until verified upload.\"\"\"
    database = db.getdb()
    candidates = database.select('cover', where='archived="'$no AND failed=$no AND id >= $minimum'"', order='id', vars={'no': False, 'minimum': 8000000}, limit=1)
    if not candidates:
        return 0
    item_id, batch_id = Cover.id_to_item_and_batch_id(candidates[0].id)
    start_id = int(item_id) * 1000000 + int(batch_id) * 10000
    end_id = CoverDB._get_batch_end_id(start_id)
    with _batch_lock(item_id, batch_id):
        covers = database.select('cover', where='id >= "'$start_id AND id <= $end_id AND archived=$no AND failed=$no'"', order='id', vars={'start_id': start_id, 'end_id': end_id, 'no': False})
        manager = ZipManager()
        count = 0
        try:
            for row in covers:
                cover = Cover(row)
                if not cover.valid_files():
                    if not test:
                        database.update('cover', where='id="'$id'"', vars={'id': row.id}, failed=True)
                    continue
                created = row.created
                if isinstance(created, str):
                    from infogami.infobase.utils import parse_datetime
                    created = parse_datetime(created)
                mtime = time.mktime(created.timetuple())
                for size in SIZES:
                    field = 'filename_' + size if size else 'filename'
                    name = f'{row.id:010d}{\"-\" + size.upper() if size else \"\"}.jpg'
                    manager.add_file(name, os.path.join(config.data_root, 'localdisk', row[field]), mtime)
                if not test:
                    database.update('cover', where='id="'$id AND archived=$no'"', vars={'id': row.id, 'no': False}, archived=True, uploaded=False)
                count += 1
        finally:
            manager.close()
        return count
