class Uploader:
    def upload(self, itemname, filepaths):
        return subprocess.run(['ia', 'upload', itemname, *filepaths], capture_output=True, text=True, check=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = subprocess.run(['ia', 'list', item], capture_output=True, text=True, check=True)
        found = zip_filename in result.stdout.splitlines()
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


def is_uploaded(item, zip_filename):
