@contextmanager
def _batch_lock(item_id, batch_id):
    \"\"\"Serialize work on a batch across processes sharing the staging directory.\"\"\"
    lockpath = Batch.get_abspath(item_id, batch_id) + '.lock'
    os.makedirs(os.path.dirname(lockpath), exist_ok=True)
    with open(lockpath, 'a+b') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id = item_id
        self.batch_id = batch_id
        self.size = size
        self._norm_ids()
        if size is not None and size not in SIZES:
            raise ValueError('invalid size')

    def _norm_ids(self):
        item_id, batch_id = int(self.item_id), int(self.batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('invalid item or batch ID')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls(item_id, batch_id)._norm_ids()
        if size not in SIZES or not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('invalid size or extension')
        item = f'{size + \"_\" if size else \"\"}covers_{item_id}'
        return os.path.join('items', item, f'{item}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        uploader = uploader or Uploader()
        item_id, batch_id = self._norm_ids()
        sizes = SIZES if self.size is None else (self.size,)
        with _batch_lock(item_id, batch_id):
            ready = True
            for size in sizes:
                path = self.get_abspath(item_id, batch_id, size)
                if not os.path.isfile(path):
                    ready = False
                    continue
                item = f'{size + \"_\" if size else \"\"}covers_{item_id}'
                if upload and not test and not uploader.is_uploaded(item, os.path.basename(path)):
                    uploader.upload(item, [path])
                if not uploader.is_uploaded(item, os.path.basename(path)):
                    ready = False
            # A cover has four variants; never publish only part of a batch.
            if finalize and ready and len(sizes) == len(SIZES) and not test:
                self.finalize()
            return ready

    def finalize(self, start_id=None, test=False):
        if test:
            return 0
        item_id, batch_id = self._norm_ids()
        return CoverDB.update_completed_batch(item_id, batch_id)


def archive(test=True):
    \"\"\"Stage one 10k ID range; keep local files until verified upload.\"\"\"
    database = db.getdb()
    candidates = database.select('cover', where='archived="'$no AND failed=$no AND id >= $minimum'"', order='id', vars={'no': False, 'minimum': 8000000}, limit=1)
    if not candidates:
        return 0
    item_id, batch_id = Cover.id_to_item_and_batch_id(candidates[0].id)
    start_id = int(item_id) * 1000000 + int(batch_id) * 10000
    end_id = CoverDB._get_batch_end_id(start_id)
    with _batch_lock(item_id, batch_id):
        covers = database.select('cover', where='id >= "'$start_id AND id <= $end_id AND archived=$no AND failed=$no'"', order='id', vars={'start_id': start_id, 'end_id': end_id, 'no': False})
        manager = ZipManager()
        count = 0
        try:
            for row in covers:
                cover = Cover(row)
                if not cover.valid_files():
                    if not test:
                        database.update('cover', where='id="'$id'"', vars={'id': row.id}, failed=True)
                    continue
                created = row.created
                if isinstance(created, str):
                    from infogami.infobase.utils import parse_datetime
                    created = parse_datetime(created)
                mtime = time.mktime(created.timetuple())
                for size in SIZES:
                    field = 'filename_' + size if size else 'filename'
                    name = f'{row.id:010d}{\"-\" + size.upper() if size else \"\"}.jpg'
